def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter as C
    flat=C(x for row in g for x in row)
    sep=None
    for r in range(H):
        cs=set(g[r])
        if len(cs)==1 and 0 not in cs and flat[list(cs)[0]]==W:
            sep=('h',r); break
    if sep is None:
        for c in range(W):
            cs={g[r][c] for r in range(H)}
            if len(cs)==1 and 0 not in cs and flat[list(cs)[0]]==H:
                sep=('v',c); break
    a=sep[1]
    if sep[0]=='h': A,B=g[:a],g[a+1:]
    else:
        A=[[row[x] for x in range(a)] for row in g]
        B=[[row[x] for x in range(a+1,W)] for row in g]
    na=sum(x!=0 for row in A for x in row); nb=sum(x!=0 for row in B for x in row)
    S,M=(A,B) if na<=nb else (B,A)
    fill=C(x for row in M for x in row).most_common(1)[0][0]
    return [[2 if (S[r][c]!=0 and M[r][c]==fill) else 0 for c in range(len(S[0]))] for r in range(len(S))]

